$assert(str_contains($view,"['SAVING', 'SUCCESS', 'ERROR', 'SESSION_EXPIRED']"),'Technical coordinator events must not be narrated automatically');
$assert(str_contains($view,'voiceController.handleEvent(event)'),'Question narration must use the single active event');
$assert(str_contains($view,'handleVoiceEvent'),'Coordinator voice events must reach the voice controller');
$assert(str_contains($view,'visibilitychange'),'Voice must stop when the page is hidden');
$assert(str_contains($view,'patient-interview-question patient-interview-active-question'),'M02 must reuse the single-question visual card');
$assert(!str_contains($view,'data-m02-defer') && !str_contains($view,'Responder después'),'M02 must not expose a defer action');
$assert(str_contains($view,'data-m02-quick'),'M02 quick responses missing');
$assert(!str_contains($view,'recognition.processLocally = true'),'The working browser recognition must not be forced into processLocally mode.');
$assert(str_contains($view,'new recognitionConstructor()'),'Local speech recognition must be detected on an instance, not only on the prototype.');
$assert(str_contains($view,'recognitionConstructor.available'),'Voice language availability is not checked when exposed by the browser.');
$assert(str_contains($view,"state === 'available'"),'Voice availability status must be recorded when the browser exposes it.');
$assert(str_contains($view,'🎙 No disponible'),'Unavailable microphone state missing');
$assert(str_contains($view,"document.createElement('button')"),'Unavailable microphone must remain an accessible explanatory control.');
$assert(str_contains($view,"indicator.addEventListener('click'"),'Unavailable microphone must explain the local-only limitation when activated.');
$assert(str_contains($view,'speechSynthesis'),'Local TTS missing');
$assert(str_contains($view,'activateAutomatically'),'Voice guide must activate automatically when the browser permits it');
$assert(str_contains($view,'AUDIO_BLOCKED'),'Autoplay blocking must remain visible and fail safe');
$assert(str_contains($view,'sessionStorage'),'Mute preference must remain scoped to the interview session');
$assert(str_contains($view,'activateAutomatically(intro'),'Automatic narration must use the server-resolved interview state');
$assert(str_contains($view,'initialInterviewState()'),'Automatic narration must use server-authorized FIRST_START or RESUME state');
$assert(str_contains($view,"initialInterviewState() === 'FIRST_START'"),'First-start narration must use the explicit FIRST_START contract event');
$assert(!str_contains($view,'hasPersistedInterviewState'),'Client-side persisted-state scan must not determine interview start');
$assert(str_contains($view,'nativeSttEnabled') && str_contains($view,'startRecognition'),'STT must remain manual and separately guarded');
$assert(str_contains($view,'stopAssistantVoice'),'TTS stop transition missing');
$assert(!str_contains($view,'Comencemos con la siguiente pregunta pendiente'),'Obsolete smoking introduction remains');
